<script setup lang="ts">
definePageMeta({ layout: 'admin' })
const authStore = useAuthStore(); if (authStore.user?.role !== 'ADMIN') throw createError({ statusCode: 403, statusMessage: 'Forbidden' })
const route=useRoute(); const service = useUsersService(); const form = reactive({ name:'', email:'', role:'MARKETING' as any, password:'' }); const errors = reactive<Record<string,string>>({}); const isLoading = ref(false)
onMounted(async()=>{ const data=await service.getById(String(route.params.id)); form.name=data.name; form.email=data.email; form.role=data.role })
const submit = async()=>{ Object.keys(errors).forEach((k)=>delete errors[k]); const parsed=userSchema.omit({password:true}).safeParse(form); if(!parsed.success){ parsed.error.issues.forEach(i=>errors[i.path[0] as string]=i.message); return } isLoading.value=true; try{ await service.update(String(route.params.id), { name: form.name, role: form.role, ...(form.password ? { password: form.password } : {}) }); await navigateTo('/admin/users') } catch(e){ errors.form=getFriendlyErrorMessage(e)} finally{ isLoading.value=false } }
</script>
<template><div class="space-y-4"><h2 class="text-2xl font-semibold">Editar usuário</h2><BaseCard><div class="grid gap-3 md:grid-cols-2"><BaseInput v-model="form.name" label="Nome" :error="errors.name"/><BaseInput v-model="form.email" type="email" label="Email" disabled/><BaseInput v-model="form.password" type="password" label="Nova senha (opcional)"/><BaseSelect v-model="form.role" label="Perfil" :options="['ADMIN','MARKETING','OPERATIONAL','COMMERCIAL'].map((r)=>({label:r,value:r}))"/></div><BaseAlert v-if="errors.form" type="error" :message="errors.form" class="mt-3"/><div class="mt-4"><BaseButton :loading="isLoading" label="Salvar alterações" @click="submit"/></div></BaseCard></div></template>
